/* 6-sinf Tarbiya — «Baxt va muvaffaqiyat sirlari» (2020). I–IV boblar */
window.T6 = window.T6 || [];
T6.push(
{id:"m1",n:"1–2-mavzu",t:"Men «oltin qoida» bo‘yicha yashayman",b:1,
 map:{c:"Axloqning «oltin qoidasi»",br:[
  {t:"Odamiylik",e:"🧑",k:["1 raqami","nollar","eng zarur xususiyat"],x:"O‘qituvchi doskaga 1 yozib, uni odamiylik dedi. Yonidagi nollar — yutuq, tajriba va boshqa fazilatlar. 1 o‘chirilsa, ma’nosiz nollar qoladi."},
  {t:"Ezgulik va yovuzlik",e:"⚖️",k:["ikki bo‘ri","tanlov","yuksalish"],x:"Rivoyatda qalbdagi yaxshi va yomon bo‘ri kurashadi. Inson qaysi birini parvarishlasa, o‘sha g‘olib bo‘ladi."},
  {t:"Axloq",e:"📜",k:["qoidalar to‘plami","burch va vijdon","adolat"],x:"Axloq — qanday xulq-atvor to‘g‘ri, qaysisi noto‘g‘ri ekanini belgilab beruvchi qoidalar to‘plami."},
  {t:"Oltin qoida",e:"🌟",k:["o‘zaro birdamlik","ko‘zgu","teng munosabat"],x:"O‘zingga qanday munosabatda bo‘lishlarini xohlasang, o‘zgalar bilan ham shunday munosabatda bo‘l."},
  {t:"Samimiy muloqot",e:"🤝",k:["salom","xushmuomalalik","va’daga vafo"],x:"Atrofdagilarga hurmat bilan murojaat qiling, xushmuomala, e’tiborli va rostgo‘y bo‘ling, hammani birdek hurmat qiling."}]},
 q:[
 {t:"m",q:"O‘qituvchi doskaga yozgan 1 raqami nimani anglatgan?",a:["Odamiylikni","Yutuqlarni","Tajribani","Boylikni"],e:"1 raqami — insonning eng zarur xususiyati, odamiyligi."},
 {t:"m",q:"O‘qituvchi 1 raqamini o‘chirgach, qanday xulosa chiqardi?",a:["Odamiylik bo‘lmasa, qolganlari befoyda","Tajriba bo‘lsa, boshqasi shart emas","Yutuqlar odamiylikdan muhimroq","Nollar qancha ko‘p bo‘lsa, shuncha yaxshi"],e:"Birsiz doskada ma’nosiz nollargina qoldi."},
 {t:"m",q:"Axloq deganda nima tushuniladi?",a:["To‘g‘ri va noto‘g‘ri xulqni belgilovchi qoidalar","Davlat qabul qilgan jazo turlari ro‘yxati","Insonning jismoniy kuchi va chidami","Kasb egallash uchun zarur bilimlar"],e:"Darslik ta’rifi: axloq — qanday xulq-atvor to‘g‘ri yoki noto‘g‘ri ekanini belgilab beruvchi qoidalar to‘plami."},
 {t:"m",q:"Boboning fikricha, qalbdagi kurashda qaysi bo‘ri g‘olib bo‘ladi?",a:["Sen parvarishlaydigan bo‘ri","Doim kuchliroq tug‘ilgan bo‘ri","Yoshi kattaroq bo‘ri","Birinchi bo‘lib hujum qilgan bo‘ri"],e:"Bobo: «Sen parvarishlaydigan bo‘ri doimo g‘olib keladi»."},
 {t:"m",q:"Rivoyatdagi yaxshi bo‘ri nimalarni ifodalaydi?",a:["Tinchlik, halollik, mehribonlik","Hasad, g‘azab, yolg‘on","Xudbinlik va shafqatsizlik","Ikkiyuzlamachilik va g‘azab"],e:"Yaxshi bo‘ri — tinchlik, muhabbat, halollik, haqiqat, mehribonlik, vafo."},
 {t:"m",q:"Axloqning «oltin qoidasi» qaysi javobda to‘g‘ri berilgan?",a:["O‘zingga istagan munosabatni o‘zgalarga ham ko‘rsat","Faqat senga yaxshilik qilganlarga yaxshilik qil","Avval o‘z foydangni o‘yla, keyin boshqalarni","Yomonlikka har doim yomonlik bilan javob ber"],e:"Ustoz bu qoidani o‘zaro birdamlik deb atagan."},
 {t:"m",q:"«Kimki ezgulik qilsa yaxshilikdir uning mevasi...» satrlari muallifi kim?",a:["Sa’diy Sheroziy","Alisher Navoiy","Abu Ali ibn Sino","Demokrit"],e:"Darslikda bu hikmat Sa’diy Sheroziy nomi bilan keltirilgan."},
 {t:"m",q:"Samimiy munosabat uchun darslik qaysi ishni maslahat beradi?",a:["Gapni salom bilan boshlash","Sinfdosh ustidan kulish","Va’dani keyinga surish","Orqasidan gapirish"],e:"Maslahat: gapingizni salom bilan boshlab, minnatdorchilik bilan tugating."},
 {t:"tf",q:"Kelajakda qanday inson bo‘lish odamning o‘ziga ham bog‘liq.",a:true,e:"Nafaqat farqlash, balki axloqiy me’yorlarga muvofiq harakat qilish ham muhim."},
 {t:"tf",q:"Badiiy asar va filmlarda ezgulik yovuzlikdan ustun kelsa, odamlar odatda xafa bo‘ladi.",a:false,e:"Aksincha, ezgulik ustun kelganda hamma xursand bo‘ladi."},
 {t:"tf",q:"Inson o‘zini boshqaning o‘rniga qo‘yib, o‘z xatti-harakatini to‘g‘rilashi kerak.",a:true,e:"Shunda atrofdagilar bilan munosabat xursandchilikka to‘la bo‘ladi."},
 {t:"f",q:"«Nima eksang, shuni o‘rasan» maqolini «oltin qoida» bilan bog‘lab tushuntiring.",e:"Boshqalarga qanday munosabatda bo‘lsak, ular ham bizga shunday munosabatda bo‘ladi: yaxshilik yaxshilik bo‘lib qaytadi."}]},

{id:"m2",n:"3–4-mavzu",t:"Rostgo‘ylik va burchni his etib yashash",b:1,
 map:{c:"Rostgo‘ylik va burch",br:[
  {t:"Rostgo‘ylik",e:"💬",k:["o‘ziga rost","o‘zgaga rost","poydevor"],x:"Rostgo‘ylik — insonlar o‘rtasidagi do‘stlik va birdamlik kabi rishtalarning poydevori."},
  {t:"Haqiqatgo‘y inson",e:"✅",k:["xatoni tan olish","adolatli baho","qonunga rioya"],x:"Haqiqatgo‘y inson xato va kamchiligini tan oladi, boshqalarni qanday mezonda baholasa, o‘zini ham shunday baholaydi."},
  {t:"Va’daga vafo",e:"⚽",k:["Said","onaga bergan so‘z","qat’iyat"],x:"Said o‘yin qizib turganda ham onasiga bergan va’dasida turib, chaqirilishi bilan uyga ketdi."},
  {t:"Vijdon",e:"🛡️",k:["qalb qalqoni","ichki ovoz","vijdon azobi"],x:"Vijdon noto‘g‘ri ish qilmoqchi bo‘lganimizda axloqiy qoidalarga rioya qilishga undovchi ichki ovozdir."},
  {t:"Sezgirlik",e:"👂",k:["his qilish","hurmat","Nigora"],x:"Sezgirlik — boshqalarni tushunish, kayfiyatini sezish va his-tuyg‘ularini hurmat qilish."}]},
 q:[
 {t:"m",q:"Rostgo‘ylik insonlar o‘rtasida nimaning poydevori hisoblanadi?",a:["Do‘stlik va birdamlikning","Boylik va shuhratning","Raqobat va bahsning","Qo‘rquv va bo‘ysunishning"],e:"Rostgo‘ylik — do‘stlik va birdamlik kabi rishtalardan poydevor."},
 {t:"m",q:"Haqiqatgo‘y inson o‘z kamchiligiga qanday qaraydi?",a:["Uni tan oladi","Boshqalardan yashiradi","Aybni o‘zgaga yuklaydi","O‘zini albatta oqlaydi"],e:"U nohaq bo‘lsa o‘zini oqlamaydi."},
 {t:"m",q:"Said nima uchun o‘yinni qoldirib, uyga yugurdi?",a:["Onasiga bergan va’dasida turish uchun","O‘yinda yutqazib qo‘ygani uchun","Do‘stlari bilan urishib qolgani uchun","Koptogi yorilib qolgani uchun"],e:"U chaqirishlari bilan kelaman deb va’da bergan edi."},
 {t:"m",q:"Darslikda vijdon nimaga o‘xshatilgan?",a:["Qalbimiz qalqoniga","Qiyshiq ko‘zguga","Qo‘sh ustunli ayvonga","Yutuq kalitiga"],e:"Vijdonni qalbimiz qalqoni deyishimiz mumkin."},
 {t:"m",q:"«Telegramma» asaridan parchada Nastya nimaga kechikdi?",a:["Onasidan kechirim so‘rashga","Maktabdagi imtihonga","Yangi ishga kirishga","Do‘stining to‘yiga"],e:"Onasi vafot etgan edi, vijdoni kech uyg‘ondi."},
 {t:"m",q:"Sinfga yangi kelgan Nigora qanday qiz edi?",a:["Uyatchan va kamgap","Maqtanchoq va sergap","Qo‘pol va janjalkash","Loqayd va dangasa"],e:"U uyatchan, kamgap, hayajonlansa duduqlanardi."},
 {t:"m",q:"Nigora bilan bo‘lgan vaziyatda Zamira va Asalga qaysi xislat yetishmadi?",a:["Sezgirlik","Qiziquvchanlik","Dadillik","Chaqqonlik"],e:"Ularning ketma-ket savollari Nigorani yig‘latdi: sezgirlik va hurmat zarur edi."},
 {t:"m",q:"«Boshqalarga nisbatan ko‘proq o‘zingdan uyalishni o‘rgan» degan fikr kimniki?",a:["Demokrit","Gyote","Shekspir","Beruniy"],e:"Demokrit yolg‘iz bo‘lsang ham yomon gapirma va yomon ish qilma, degan."},
 {t:"tf",q:"Vijdon azobi yolg‘on yoki nojo‘ya harakat natijasida paydo bo‘ladi.",a:true,e:"Bu ichki bezovtalik va aybdorlik hissi."},
 {t:"tf",q:"Sezgirlik rostgo‘ylik bilan bog‘liq bo‘lmagan, unga zid xislatdir.",a:false,e:"Darslikda rostgo‘ylik sezgirlik xislatiga ham bog‘liq deyilgan."},
 {t:"tf",q:"Said do‘stiga onasi eshitganini bilmasa ham, o‘zi bilishini aytdi.",a:true,e:"Bu — o‘ziga nisbatan ham rostgo‘ylik namunasi."},
 {t:"f",q:"O‘ziga nisbatan va boshqalarga nisbatan rostgo‘ylik qanday namoyon bo‘ladi? Misol keltiring.",e:"O‘ziga: xatosini tan olish, o‘zini aldamaslik. Boshqalarga: yolg‘on gapirmaslik, va’dada turish."}]},

{id:"m3",n:"5-mavzu",t:"Adolat – hayot haqiqati",b:1,
 map:{c:"Adolat",br:[
  {t:"Adolat nima",e:"⚖️",k:["baholash","jazolash","mukofotlash"],x:"Adolat — xatti-harakatlarni oqibatiga ko‘ra ezgulik va yovuzlik nuqtayi nazaridan baholab, shunga qarab jazolash yoki mukofotlash."},
  {t:"Qonun va axloq",e:"📘",k:["huquqiy qoidalar","davlat","yozilmagan qoida"],x:"Huquqiy munosabatlar qonunlarda aks etadi va davlat tartibga soladi; axloqiy qoidalar yozilmasa ham odamlar ularga amal qiladi."},
  {t:"Adolatli munosabat",e:"🙏",k:["ezgulikka ezgulik","minnatdorlik","kechirim"],x:"Ezgulikka ezgulik bilan javob berish, minnatdorchilik bildirish, nohaq xafa qilgani uchun kechirim so‘rash."},
  {t:"Muallim va asal",e:"🍯",k:["ikki chelak","katta va kichik idish","munosib ulush"],x:"Muallim ishni qanday taqsimlagan bo‘lsangiz, asalni ham shunday taqsimlang, dedi."},
  {t:"Hikmat va timsol",e:"🏛️",k:["Amir Temur","Femida","tarozi"],x:"Amir Temur: adolat davlatning asosi. Qadimgi Yunonistonda adolat timsoli — Femida: tarozi, qilich, ko‘z bog‘ichi."}]},
 q:[
 {t:"m",q:"Huquqiy munosabatlar nimada o‘z aksini topgan?",a:["Qonunlarda","Rivoyatlarda","Maqollarda","Ertaklarda"],e:"Qonunlar davlat tomonidan tartibga solinadi."},
 {t:"m",q:"Axloqiy va ma’naviy qoidalarning o‘ziga xosligi nimada?",a:["Yozilmagan bo‘lsa ham odamlar amal qiladi","Faqat sud qarori bilan kuchga kiradi","Faqat maktab ichida amal qiladi","Har yili davlat tomonidan almashtiriladi"],e:"Ular hech qayerda yozilmagan, lekin odamlar rioya qiladi."},
 {t:"m",q:"Axloqiy nuqtayi nazardan adolatli munosabatga qaysi misol kiradi?",a:["Nohaq xafa qilgach, kechirim so‘rash","Aybni sinfdoshga ag‘darib qo‘yish","Yaxshilikni sezmaganga olish","Do‘stga uy vazifasini ko‘chirtirish"],e:"Boshqa misollar: ezgulikka ezgulik, minnatdorchilik."},
 {t:"m",q:"Muallim oldiga yordamga kelgan yigitlar qaysi ishni bajarishdi?",a:["Quduqdan suv tashishdi","Hovliga daraxt ekishdi","Uy tomini ta’mirlashdi","O‘tin yorib berishdi"],e:"Biri katta, ikkinchisi kichik chelakda suv tashidi."},
 {t:"m",q:"Muallim asalni taqsimlash haqida nima dedi?",a:["Ishni qanday taqsimlagan bo‘lsangiz, shunday taqsimlang","Yoshi kattangiz katta idishni olsin","Ikkala idishni aralashtirib, teng bo‘ling","Kim birinchi qo‘l uzatsa, o‘sha tanlasin"],e:"Bu hikoya adolat — mehnatga yarasha ulush ekanini o‘ylatadi."},
 {t:"m",q:"«Adolat davlatning asosi va hukmdorlar shioridir» hikmati kimga tegishli?",a:["Amir Temur","Alisher Navoiy","Ulug‘bek","Bobur"],e:"Darslikdagi hikmat — Amir Temur so‘zi."},
 {t:"m",q:"Qadimgi yunon mifologiyasida adolatni qaysi ma’buda aks ettirgan?",a:["Femida","Afina","Gera","Artemida"],e:"Femida adolat, qonun va tartib-intizom timsoli."},
 {t:"m",q:"Femidaning atributlari qaysi qatorda?",a:["Tarozi, qilich, ko‘z bog‘ichi","Qalqon, nayza, dubulg‘a","Kitob, qalam, chiroq","Toj, hassa, kalit"],e:"Uchta asosiy atribut: tarozi, qilich va ko‘zidagi bog‘ich."},
 {t:"tf",q:"Adolat faqat jazolashni anglatadi, mukofotlash unga kirmaydi.",a:false,e:"Adolat — baholab, shunga qarab jazolash yoki mukofotlash."},
 {t:"tf",q:"Muallimning sobiq o‘quvchilari avval asalni o‘zlari taqsimlay olmasliklarini aytishdi.",a:true,e:"Ular xijolat tortib: «Biz buni taqsimlay olmaymiz», deyishdi."},
 {t:"tf",q:"Shavkat Mirziyoyev qonun va adolat uchun kurashadiganlar bugungi kun qahramonlari bo‘lishi kerakligini aytgan.",a:true,e:"Bu hikmat darslikda keltirilgan."},
 {t:"f",q:"Do‘stingiz gultuvakni sindirib, aybni boshqaga ag‘darsa, qanday adolatli yo‘l tutasiz?",e:"Do‘stga haqiqatni aytishni va kechirim so‘rashni maslahat beraman; aybsiz sinfdosh nohaq jazolanmasligi kerak."}]},

{id:"m4",n:"6–7-mavzu",t:"Minnatdorlik yuragimda yashaydi",b:1,
 map:{c:"Minnatdorlik",br:[
  {t:"Ta’rif",e:"💛",k:["yaxshilik","iliq his","qadrlash"],x:"Minnatdorchilik — ko‘rsatilgan yaxshilik uchun minnatdorlik hissi."},
  {t:"Yaxshi «virus»",e:"🔁",k:["tarqaladi","rahmat","yangi yaxshilik"],x:"«Rahmat» eshitgan odam unga munosib bo‘lish uchun yana yaxshilik qilishga intiladi."},
  {t:"Izhor usullari",e:"✉️",k:["xat","she’r va qo‘shiq","rasm"],x:"Minnatdorchilik so‘z, xat, she’r, qo‘shiq, rasm hamda qo‘lni ko‘ksiga qo‘yish kabi ishora bilan bildiriladi."},
  {t:"Ikki toifa",e:"👥",k:["minnatdor","noshukur","shikoyat"],x:"Noshukur odam doim norozi bo‘ladi; minnatdor odamning do‘stlari ko‘p va uni hurmat qilishadi."},
  {t:"Borini qadrlash",e:"🕊️",k:["tinch osmon","maktab","Zidan"],x:"Tinch hayot, maktab, o‘rganish imkoniyati — minnatdor bo‘ladigan narsalar ro‘yxati juda uzun."}]},
 q:[
 {t:"m",q:"Minnatdorchilik nima?",a:["Ko‘rsatilgan yaxshilik uchun minnatdorlik hissi","Qilingan ish uchun to‘lanadigan pul","Xafa qilgan odamdan o‘ch olish istagi","Boshqalardan doim yordam kutish odati"],e:"Foydali va xayrli ishni iliq his va ijobiy fikr bilan qadrlash."},
 {t:"m",q:"Darslikda minnatdorchilik nimaga o‘xshatilgan?",a:["Yaxshi «virus»ga","Qiyshiq ko‘zguga","O‘tkir qilichga","Chuqur quduqqa"],e:"U yaxshi «virus» kabi tarqalishi mumkin."},
 {t:"m",q:"Turli millat vakillari so‘zsiz minnatdorchilikni qaysi ishora bilan bildiradi?",a:["Qo‘lni ko‘ksiga qo‘yib","Qo‘lni yuqori ko‘tarib","Yelkani qisib qo‘yib","Barmog‘ini silkitib"],e:"Bu ishora ko‘pchilikka tushunarli."},
 {t:"m",q:"Qaysi odam noshukur toifaga kiradi?",a:["Doim norozi bo‘lib, shikoyat qiladigan","Kichik e’tibor uchun ham rahmat aytadigan","Atrofidagi olamni qadrlaydigan","Yaqinlariga minnatdorlik xati yozadigan"],e:"Noshukurlarga nimadir doim yetishmaydi."},
 {t:"m",q:"«Agar daraxt senga o‘z soyasi, mevalari va gullarini taqdim etsa...» hikmati kimniki?",a:["Vasishtxa, hind donishmandi","Luqmoni hakim","Demokrit","Mahatma Gandi"],e:"Hikmat minnatdorlik evaziga daraxtni yulib olmaslik haqida."},
 {t:"m",q:"Zinedin Zidan bolaligida nima yo‘qligidan yig‘lagan edi?",a:["Futbol o‘ynash uchun oyoq kiyimi","Futbol to‘pi va darvoza","Mashg‘ulotga boradigan puli","Jamoa formasi va raqami"],e:"Keyin u oyoqlari yo‘q insonni ko‘rib qoldi."},
 {t:"m",q:"E’tiborli odam bo‘lish uchun darslik nima qilishni taklif etadi?",a:["Ekranlardan uzilib, atrofga nazar tashlash","Ko‘proq video tomosha qilib o‘rganish","Faqat o‘z ishlari bilan band bo‘lish","Kamchiliklarni daftarga yozib borish"],e:"Televizor, planshet, smartfondan bir necha daqiqa uzoqlashib, olamga qarang."},
 {t:"m",q:"Kechasi isitmangiz ko‘tarilgan vaziyatda ota-ona qanday g‘amxo‘rlik qildi?",a:["Dori olib kelib, tun bo‘yi qarab chiqishdi","Ertalabgacha kutib turishni aytishdi","Sizni do‘stingiznikiga yuborishdi","Faqat issiq choy qoldirib ketishdi"],e:"Dadasi dorixonaga chiqdi, onasi tun bo‘yi yonida o‘tirdi."},
 {t:"tf",q:"Minnatdorchilikni faqat so‘z bilan bildirish mumkin.",a:false,e:"Xat, she’r, qo‘shiq, rasm va ishoralar bilan ham bildiriladi."},
 {t:"tf",q:"O‘ziga ham minnatdorchilik bildirish muhim.",a:true,e:"Darslik: kimgadir va o‘zimizga minnatdorchilik bildirish juda muhim."},
 {t:"tf",q:"Ozgina e’tibor uchun ham bir-birimizga minnatdorchilik bildirish tavsiya etiladi.",a:true,e:"«Rahmat» so‘zini hech qachon unutmaslik kerak."},
 {t:"f",q:"Bugun kimga va nima uchun minnatdorsiz? Minnatdorligingizni qanday izhor etasiz?",e:"Masalan: ota-onaga g‘amxo‘rligi uchun, ustozga ta’limi uchun; so‘z, xat, rasm yoki yordam bilan."}]},

{id:"m5",n:"8-mavzu",t:"Kechirimlilik kuchlilar xislatidir",b:1,
 map:{c:"Kechirimlilik",br:[
  {t:"Xafagarchilik",e:"😔",k:["nohaq zarar","g‘azab","qalb jarohati"],x:"Xafagarchilik — nohaq zarar yetkazilganda his etiladigan, munosabatlarni buzadigan tuyg‘u."},
  {t:"G‘ijimlangan qog‘oz",e:"📄",k:["iz qoladi","ehtiyot bo‘lish","qalb"],x:"G‘ijimlangan qog‘ozni avvalgidek tekislab bo‘lmaydi: birovni xafa qilishdan oldin o‘ylash kerak."},
  {t:"Kechirim so‘rash",e:"🙇",k:["«Kechiring»","aybni tan olish","amal bilan"],x:"Kechirim «Kechirasiz», «Mendan ayb o‘tdi» kabi so‘zlar bilan yoki xatti-harakat va muomala bilan so‘raladi."},
  {t:"Qoidalar",e:"📝",k:["hamma xato qiladi","kechiring","eng yaxshi davo"],x:"Hamma xato qilishi mumkin; kechiring — sizni ham kechirishadi; kechirish — g‘azab va nafratga eng yaxshi davo."},
  {t:"Tajriba",e:"🧪",k:["suv — qalb","bo‘yoq — xafalik","oqartiruvchi — kechirim"],x:"Tajribada suv inson qalbini, bo‘yoq xafagarchilikni, oqartiruvchi modda kechirimni bildiradi."}]},
 q:[
 {t:"m",q:"Uzoq saqlangan xafagarchilik insonni nimaga olib keladi?",a:["G‘azablantiradi va yaqinlaridan mahrum qiladi","Chiniqtiradi va do‘stlarini ko‘paytiradi","Sabrli qiladi va xotirasini kuchaytiradi","Hech qanday ta’sir qilmay unutiladi"],e:"U munosabat va kayfiyatni buzadi."},
 {t:"m",q:"Darslikda xafagarchilik qanday ataladi?",a:["Qalb jarohati","Qalb qalqoni","Yutuq kaliti","Sog‘liq garovi"],e:"«Xafagarchilik — bu qalb jarohati»."},
 {t:"m",q:"G‘ijimlangan qog‘oz tajribasida qog‘oz kimni ifodalaydi?",a:["Xafa qilingan insonni","Kechirgan o‘qituvchini","Aybini yashirganni","Befarq kuzatuvchini"],e:"Qog‘ozni dastlabki holiga to‘liq qaytarish qiyin."},
 {t:"m",q:"Suv, bo‘yoq va oqartiruvchi modda tajribasida kechirimni nima bildiradi?",a:["Oqartiruvchi modda","Shaffof stakan","Oziq-ovqat bo‘yog‘i","Stakandagi suv"],e:"Oqartiruvchi modda — kechirim."},
 {t:"m",q:"Darslikka ko‘ra, kechirim so‘rashning eng oson yo‘li qaysi?",a:["«Kechiring» kabi so‘zlarni aytish","Bir necha kun gapirmay yurish","O‘rtadagi odam orqali sovg‘a yuborish","Voqeani unutgandek tutish"],e:"Bolalikdan tanish so‘zlar: «Kechirasiz», «Mendan ayb o‘tdi»."},
 {t:"m",q:"Nohaqligini sezgan, lekin so‘z bilan ayta olmaydigan odam nima qiladi?",a:["Xatti-harakati va muomalasi bilan ko‘rsatadi","Aybni boshqa odamga yuklab qutuladi","Xafa bo‘lib, aloqani butunlay uzadi","O‘zini haq deb bahslashishda davom etadi"],e:"Bu ham kechirim so‘rashning bir usuli."},
 {t:"m",q:"Kechirishga qodir insonga qaysi so‘zlar qatori mos?",a:["Sabr-toqat, rahm-shafqat, samimiylik","Nafrat, jahl, xudbinlik","Alam, darg‘azablik, nafrat","Jahl, xudbinlik, alam"],e:"Salbiy tuyg‘ular kechirishga xalaqit beradi."},
 {t:"m",q:"Devoriy gazeta vaziyatida jamoa a’zolari sizga nima deyishdi?",a:["Chizishni bilmaysiz, faqat xalaqit qilasiz","Eng yaxshi rassom sifatida qabul qilamiz","Keyingi tanlovda albatta birga bo‘lamiz","Sizga sarlavha yozishni ishonib topshiramiz"],e:"Bunday muomala insonni xafa qiladi."},
 {t:"tf",q:"Hamma ham xato qilishi mumkin.",a:true,e:"Bu xafagarchilikni yengishning birinchi qoidasi."},
 {t:"tf",q:"G‘azab va nafratga qarshi eng yaxshi davo — uzoq vaqt gina saqlash.",a:false,e:"Eng yaxshi davo — kechirish."},
 {t:"tf",q:"Aybni tan olishni o‘rganish kerak.",a:true,e:"Bu maslahatlar ro‘yxatidagi qoida."},
 {t:"f",q:"Nima uchun kechirimlilik kuchlilar xislati deyiladi?",e:"Aybni tan olish va ginani yengish jasorat, sabr va rahm-shafqat talab qiladi."}]},

{id:"m6",n:"9-mavzu",t:"Sabr-toqatlilik",b:1,
 map:{c:"Sabr-toqatlilik",br:[
  {t:"Sabr ta’rifi",e:"⏳",k:["chidam","bardosh","o‘zini tiyish"],x:"Sabr (chidam, bardosh, iroda) — holat yoki hodisani bardosh bilan kutish, qanoat qilish, o‘zini tiyish."},
  {t:"Maqsad sari",e:"🎯",k:["taslim bo‘lmaslik","ildam borish","mehnatsevarlik"],x:"Sabrlilik taslim bo‘lmaslik va maqsad sari borishni o‘rgatadi."},
  {t:"Kundalik sabr",e:"🏫",k:["dars tinglash","navbat","uy vazifasi"],x:"Maktabda dars tinglash, navbatda turish, ukaga qarash — har kungi sabr holatlari."},
  {t:"Hikmatlar",e:"📚",k:["sara oltin","yutuq kaliti","Navoiy"],x:"«Sabr tagi — sara oltin», «Sabr — yutuq kaliti»."},
  {t:"Mashq",e:"🫘",k:["50 gramm mosh","10–15 daqiqa","7 kun"],x:"Moshni birma-bir terish mashqi kuniga 10–15 daqiqadan 7 kun bajariladi."}]},
 q:[
 {t:"m",q:"Millioner boyishiga qaysi xislati yordam berganini aytdi?",a:["Sabrlilik","Ayyorlik","Tavakkalchilik","Shoshqaloqlik"],e:"U «Sabrlilik» deb javob berdi."},
 {t:"m",q:"Elakda suv keltirish haqidagi savolga millioner qanday javob berdi?",a:["«Qish kelsin, buning ham yechimi topiladi»","«Bunda sabr umuman yordam bermaydi»","«Elakni boshqa idishga almashtiraman»","«Bu ishni boshqa odamga topshiraman»"],e:"Sabr bilan kutilsa, yechim topiladi."},
 {t:"m",q:"Sabr tushunchasiga qaysi ta’rif mos?",a:["Bardosh bilan kutish va o‘zini tiyish","Har ishni tezroq tugatishga intilish","Qiyin ishdan darhol voz kechish","Navbatni kutmay birinchi bo‘lish"],e:"Sabr — kutish, qanoat qilish, o‘zini tiyish."},
 {t:"m",q:"Yoqmagan ishni bajarishga to‘g‘ri kelsa, sabr bilan birga nima yordam beradi?",a:["Mehnatsevarlik","Qiziquvchanlik","Raqobat","Omad"],e:"Sabrlilik va mehnatsevarlik xislati yordam beradi."},
 {t:"m",q:"Qaysi vaziyatda sabrsizlik tasvirlangan?",a:["Navbati kelmasdan javob bermoqchi bo‘lish","Yuzlab pazl bo‘lagini soatlab yig‘ish","Oshxonada navbat kamayishini kutish","Darsni diqqat bilan oxirigacha tinglash"],e:"Partadosh navbatidan oldin qo‘l cho‘zdi."},
 {t:"m",q:"Maqolni to‘ldiring: «Bardoshliga ...».",a:["yog‘li osh","sara oltin","yutuq kaliti","asl boylik"],e:"Maqol: «Bardoshliga yog‘li osh»."},
 {t:"m",q:"«Har kimsaki, aylamas oshuqmoqni xayol, Yaproqni ipak qilur...» misralari muallifi kim?",a:["Alisher Navoiy","Sa’diy Sheroziy","Erkin Vohidov","Abdulla Avloniy"],e:"Navoiy shoshilmaslik — sabrning mevasini ta’riflaydi."},
 {t:"m",q:"Sabrni mashq qilish uchun laboratoriya ishida nima ishlatiladi?",a:["Mosh va kichik quticha","Guruch va katta idish","Qum soati va qog‘oz","Pazl va yelim"],e:"50 gramm mosh birma-bir teriladi."},
 {t:"tf",q:"Sabrlilik insonni hech qachon taslim bo‘lmaslikka o‘rgatadi.",a:true,e:"U maqsad sari ildam borishni ham o‘rgatadi."},
 {t:"tf",q:"Inson har kuni sabr qilish holatiga duch kelganini doim albatta sezadi.",a:false,e:"Darslik: buni o‘zingiz hatto sezmasligingiz ham mumkin."},
 {t:"tf",q:"«Asl boylik — qanoat» maqoli sabr mavzusida keltirilgan.",a:true,e:"Sabr ta’rifida qanoat qilish ham bor."},
 {t:"f",q:"Qaysi vaziyatda sabr qilish sizga qiyin bo‘ladi? Sabrli bo‘lish uchun nima qilasiz?",e:"Masalan: navbat kutish yoki sovg‘ani kutish. Maqsadni eslash, foydali ish bilan band bo‘lish, mashq qilish."}]},

{id:"m7",n:"10-mavzu",t:"Ona yurtim – oltin beshigim",b:2,
 map:{c:"Ona yurt",br:[
  {t:"Faxr manbalari",e:"🇺🇿",k:["non isi","tarixiy obidalar","raqs va kuy"],x:"Nonning xushbo‘y isi, kuy-laparlar, raqslar, obidalar, dorbozlar yurtdoshlar va mehmonlarni befarq qoldirmaydi."},
  {t:"Sadoqat",e:"🛡️",k:["sarhad himoyasi","til va e’tiqod","urf-odat"],x:"Vatanga sodiqlik — uning sarhadlarini himoya qilish, xalqning tili, e’tiqodi va urf-odatlarini sevish."},
  {t:"Kindik qoni",e:"🏡",k:["tug‘ilgan yer","muqaddas dargoh","sog‘inch"],x:"Inson qayerda dunyoga kelsa, o‘sha yer ona Vatani; kindik qoni to‘kilgan joy muqaddas."},
  {t:"Allomalar so‘zi",e:"✒️",k:["Navoiy","Fitrat","Anbar Otin"],x:"Fitrat: Vatan mening jon-u tanim, sajdagohimdir. Anbar Otin Vatanni ikkinchi ona deydi."},
  {t:"Lolaxon Murodova",e:"🚜",k:["mexanizator","halol mehnat","Qahramon"],x:"Dehqon oilasida o‘sgan Lolaxon Murodova mexanizator bo‘ldi va «O‘zbekiston Qahramoni» unvonini oldi."}]},
 q:[
 {t:"m",q:"Darslikka ko‘ra, qaysi yer insonning ona Vatani hisoblanadi?",a:["U dunyoga kelgan yer","U dam olishga boradigan yer","U kitobda o‘qigan yer","U eng ko‘p xarid qiladigan yer"],e:"Inson farzandi qayerda tug‘ilsa, o‘sha yer uning Vatani."},
 {t:"m",q:"«Vatan tarkini bir nafas aylama...» baytining muallifi kim?",a:["Alisher Navoiy","Abdurauf Fitrat","Anbar Otin","Erkin Vohidov"],e:"Bu so‘zlar qalbda g‘ayrat va shijoat uyg‘otadi."},
 {t:"m",q:"«Vatan mening jon-u tanim, sajdagohimdir» degan fikr kimga tegishli?",a:["Abdurauf Fitrat","Abdulla Avloniy","Hamza","Navoiy"],e:"Darslikda Abdurauf Fitrat hikmati sifatida berilgan."},
 {t:"m",q:"Anbar Otin baytida Vatan nimaga qiyoslanadi?",a:["Ikkinchi onaga","Oltin kalitga","Buyuk maktabga","Katta bog‘ga"],e:"«Vatan erur senga ikkinchi ona»."},
 {t:"m",q:"Lolaxon Murodova maktabni tugatgach qaysi kasbga o‘qidi?",a:["Mexanizatorlikka","Shifokorlikka","O‘qituvchilikka","Muhandislikka"],e:"«Qiz bolaga og‘irlik qiladi» degan gaplarga quloq solmadi."},
 {t:"m",q:"Lolaxonning otasi unga texnikani boshqarish nimaga bog‘liqligini aytgan?",a:["O‘ziga bo‘lgan ishonchga","Traktorning yangiligiga","Yerning tekisligiga","Ob-havoning qulayligiga"],e:"«Aslo ikkilanma», degan otasi."},
 {t:"m",q:"Vatanga sodiqlik nimani o‘z ichiga oladi?",a:["Sarhadni himoya qilish, til va urf-odatni sevish","Faqat bayram kunlari yurtni maqtab qo‘yish","Faqat o‘z uyi va hovlisini o‘ylab yashash","Boshqa yurtlarni o‘rganishdan bosh tortish"],e:"Himoya va xalqning tili, e’tiqodi, urf-odatlarini sevish."},
 {t:"m",q:"Lolaxon Murodova qaysi unvon bilan taqdirlangan?",a:["O‘zbekiston Qahramoni","Xalq o‘qituvchisi","Xalq artisti","Sog‘liqni saqlash a’lochisi"],e:"Halol mehnati uchun shu unvonga sazovor bo‘ldi."},
 {t:"tf",q:"Sharq xalqlari uchun Vatan mo‘tabar makon sanaladi.",a:true,e:"Butun dunyo xalqlari ona yurtni aziz biladi, ayniqsa Sharq xalqlari."},
 {t:"tf",q:"Lolaxon Murodova shahar ziyolilari oilasida birinchi farzand bo‘lgan.",a:false,e:"U oddiy dehqon oilasida ikkinchi farzand edi."},
 {t:"tf",q:"Lolaxon maktab o‘quvchisi bo‘lganidayoq ota-onasi bilan dalaga chiqar edi.",a:true,e:"U ekishdan paxta terimigacha ularning yonida bo‘lgan."},
 {t:"f",q:"Vatanimiz ravnaqiga hozirdan qanday hissa qo‘sha olasiz?",e:"Masalan: yaxshi o‘qish, kasb o‘rganish, tabiat va obidalarni asrash, mahallaga yordam berish."}]},

{id:"m8",n:"11–12-mavzu",t:"Mening mahallam – mening faxrim",b:2,
 map:{c:"Mahalla",br:[
  {t:"Mahalla nima",e:"🏘️",k:["arabcha so‘z","o‘zini boshqarish","jamoa"],x:"Mahalla — o‘z-o‘zini boshqarishning an’anaviy usuli; arabcha so‘z «o‘rin», «joy» ma’nosini bildiradi."},
  {t:"Boshqaruv",e:"👤",k:["rais","3 yil","faollar"],x:"Mahallani rais boshqaradi; u aholi tomonidan 3 yilga saylanadi. Rais va faollar to‘y, marosim, hasharlarda ishtirok etadi."},
  {t:"Tamoyillar",e:"⚖️",k:["ochiqlik","ijtimoiy adolat","insonparvarlik"],x:"Asosiy tamoyillar: ochiqlik, oshkoralik, ijtimoiy adolat, insonparvarlik, mahalliy masalalarni hal qilishda erkinlik."},
  {t:"Mening hissam",e:"🌳",k:["tejamkorlik","rahmdillik","hashar"],x:"Suv, elektr va gazni tejash, keksalardan xabar olish, daraxt ekish, hasharda qatnashish."},
  {t:"Qo‘shni haqi",e:"🍑",k:["Umida","Dilbar momo","o‘rik"],x:"Qo‘shni ilinib bergan mevaga pul to‘lanmaydi; idish non va qand-qurs bilan qaytariladi."}]},
 q:[
 {t:"m",q:"«Mahalla» so‘zi qaysi tildan olingan?",a:["Arab tilidan","Fors tilidan","Rus tilidan","Yunon tilidan"],e:"Arabcha so‘z bo‘lib, «o‘rin», «joy» degani."},
 {t:"m",q:"Darslikka ko‘ra, mahalla raisi necha yilga saylanadi?",a:["3 yilga","1 yilga","7 yilga","10 yilga"],e:"Rais mahalla aholisi tomonidan 3 yilga saylanadi."},
 {t:"m",q:"O‘tmishda mahalla chegarasi nimaga qarab belgilangan?",a:["Muazzin ovoziga","Ariq yo‘nalishiga","Bozor masofasiga","Devor balandligiga"],e:"Muazzin ovozini eshitgan aholi bir mahalla qo‘shnilari hisoblangan."},
 {t:"m",q:"Mahalla tamoyillari qatoriga qaysi biri kiradi?",a:["Ijtimoiy adolat","Maxfiy boshqaruv","Shaxsiy manfaat","Majburiy raqobat"],e:"Ochiqlik, oshkoralik, ijtimoiy adolat, insonparvarlik."},
 {t:"m",q:"Mol-mulkka ehtiyotkorlik bilan munosabatga qaysi misol mos?",a:["Suv va gazdan oqilona foydalanish","Qushlarga don berib turish","Bolalar uchun o‘yin uyushtirish","Notanish odam haqida xabar berish"],e:"Shuningdek, chiqindini belgilangan joyga tashlash."},
 {t:"m",q:"Notanish kishi kimnidir tinimsiz kuzatayotganini ko‘rsangiz, nima qilish kerak?",a:["Kattalarni xabardor qilish","O‘zingiz uning ortidan yurish","E’tibor bermay o‘tib ketish","U bilan tanishib olish"],e:"Bu hushyorlik: shubhali holat haqida kattalarga aytiladi."},
 {t:"m",q:"Dilbar momo qo‘shnidan kelgan o‘rik idishini qanday qaytardi?",a:["Ichiga non va qand-qurs solib","Ichiga o‘rik puli qo‘yib","Bo‘sh holida eshikka qo‘yib","Ichiga xat yozib qo‘yib"],e:"Idish bo‘sh qaytarilmadi; mevaga pul berish uyat sanaladi."},
 {t:"m",q:"Umida Doniyorga qo‘shni bog‘idagi o‘rikni nega yedirmadi?",a:["Uning egasi bor edi","Mevasi hali g‘o‘r edi","Doniyor kasal edi","Tushlik vaqti edi"],e:"«Bu o‘rikning egasi bor», dedi Umida."},
 {t:"tf",q:"Mahalla hasharlar uyushtirishda ishtirok etadi.",a:true,e:"Rais va faollar to‘y, marosim, bayram va hasharlarni tashkillashtiradi."},
 {t:"tf",q:"Dilbar momoning fikricha, qo‘shni bergan meva uchun albatta pul to‘lash shart.",a:false,e:"«Buning puli berilmaydi» — bu qo‘shni haqi."},
 {t:"tf",q:"Ba’zi mahallalar hududidagi diqqatga sazovor joylar nomi bilan atalgan.",a:true,e:"Ba’zan aholi ko‘chib kelgan shahar yoki qishloq nomi ham berilgan."},
 {t:"f",q:"Mahallangiz uchun qanday foydali ish qila olasiz? Uchta misol yozing.",e:"Masalan: hasharda qatnashish, ko‘chat ekish, keksalardan xabar olish, chiqindini to‘g‘ri tashlash."}]},

{id:"m9",n:"13–14-mavzu",t:"Xatti-harakat qanday bo‘lsa, oqibat ham shunday bo‘ladi",b:2,
 map:{c:"Xatti-harakat va oqibat",br:[
  {t:"Tushuncha",e:"🚶",k:["xulq-atvor","yurish-turish","shaxsni baholash"],x:"Xatti-harakat — insonning xulq-atvori, yurish-turishi; u qanday shaxs ekanini ko‘rsatadi."},
  {t:"Ketma-ketlik",e:"➡️",k:["fikr","harakat","natija"],x:"Avval fikr, so‘ng harakat, keyin natija. «Yetti o‘lchab, bir kes»."},
  {t:"Qahramonlik",e:"🦸",k:["mardlik","fidokorlik","ezgu amal"],x:"Qahramonlik fidokorlikni talab etadi; oila va jamiyat uchun astoydil qilingan ezgu amal ham qahramonlikdir."},
  {t:"Ko‘za saboqi",e:"🏺",k:["toshlar","no‘xat va qum","vaqt"],x:"Avval eng muhim narsalar — oila, sog‘liq, aziz kishilar; aks holda mayda ishlarga vaqt ketib qoladi."},
  {t:"Noo‘rin harakat",e:"🚫",k:["chiptasiz yurish","qoida buzish","masxara"],x:"Umumqabul qilingan me’yorlarni buzish: chiptasiz yurish, yo‘l harakati va texnika xavfsizligi qoidalarini buzish."}]},
 q:[
 {t:"m",q:"Harakatni amalga oshirishning to‘g‘ri ketma-ketligi qaysi?",a:["Fikr, harakat, natija","Harakat, fikr, natija","Natija, harakat, fikr","Harakat, natija, fikr"],e:"Avval o‘ylanadi, so‘ng bajariladi, keyin natija ko‘rinadi."},
 {t:"m",q:"Harakatni o‘ylab bajarishga undovchi maqol qaysi?",a:["Yetti o‘lchab, bir kes","Toma-toma ko‘l bo‘lur","Salomga yarasha alik","Do‘st og‘ir kunda bilinadi"],e:"Dono xalqimiz bejiz shunday demagan."},
 {t:"m",q:"Qahramonlik avvalo nimani talab etadi?",a:["Fidokorlikni","Shuhratni","Boylikni","Chaqqonlikni"],e:"Mardonavor harakat va fidokorlik."},
 {t:"m",q:"Donishmand hikoyasida toshlar nimani anglatadi?",a:["Aziz kishilar, oila va sog‘liqni","Uy, mashina va yaxshi ishni","Hayotdagi mayda-chuyda narsalarni","Bekor o‘tadigan bo‘sh vaqtni"],e:"No‘xat — ish, uy, mashina; qum — mayda narsalar."},
 {t:"m",q:"Ko‘zani avval qum bilan to‘ldirsak, nima bo‘ladi?",a:["No‘xat va toshlarga joy qolmaydi","Toshlar osonroq joylashadi","Ko‘za tezda yorilib ketadi","Suv quyishga hojat qolmaydi"],e:"Vaqtni bekorchi narsalarga sarflasak, asosiysiga vaqt qolmaydi."},
 {t:"m",q:"Shogird yaxshilik qilib qaytgach nega g‘azablandi?",a:["Ayrimlar rahmat ham aytishmagani uchun","Ustozi unga ovqat bermagani uchun","Qishloqqa yo‘l topa olmagani uchun","Muhtoj odam umuman bo‘lmagani uchun"],e:"Ustoz yaxshilikni savdoga aylantirmaslikni uqtirdi."},
 {t:"m",q:"Jurnalist yolg‘iz keksani masxara qilishayotganini eshitib nima qildi?",a:["Uyini ta’mirlash uchun murojaat yozdi","Masxarachilarga qo‘shilib kulib qo‘ydi","Shoshilib ishiga ketib, voqeani unutdi","Keksaga boshqa joyga ko‘chishni aytdi"],e:"O‘sha kuniyoq javob oldi va ta’mir boshlandi."},
 {t:"m",q:"Qaysi biri noo‘rin xatti-harakat?",a:["Transportda chiptasiz yurish","Keksaga joy bo‘shatib berish","Singlisiga vazifada yordamlashish","Ukasini bog‘chadan olib kelish"],e:"Bu jamoat qoidalarini buzishdir."},
 {t:"tf",q:"Harakatlar so‘z va imo-ishoralar orqali ham amalga oshirilishi mumkin.",a:true,e:"Darslikda shunday ta’kidlangan."},
 {t:"tf",q:"Ustoz fikricha, yaxshilikni maqtov va shuhrat qozonish uchun qilish kerak.",a:false,e:"Inson yaxshilikni hurmat, shuhrat yoki maqtanish uchun qilmasligi kerak."},
 {t:"tf",q:"«Nihol» she’rida yurtdoshga bog‘ga nihol qadash taklif etiladi.",a:true,e:"Erkin Vohidov niholni yaxshilik deb atashni so‘raydi."},
 {t:"f",q:"«Aytilgan so‘z — otilgan o‘q» maqolini xatti-harakat oqibati bilan bog‘lab tushuntiring.",e:"Aytilgan so‘zni qaytarib bo‘lmaydi, u dilni og‘ritishi mumkin; shuning uchun avval o‘ylab gapirish kerak."}]},

{id:"m10",n:"15–16-mavzu",t:"Bilim ol, kasb-hunar tanla!",b:2,
 map:{c:"Bilim va kasb",br:[
  {t:"Bilim",e:"📖",k:["maktab fanlari","tillar","amalda qo‘llash"],x:"Gyote: bilimning o‘zi yetarli emas, uni amalda qo‘llay bilish ham kerak."},
  {t:"Malaka va ko‘nikma",e:"🛠️",k:["tajriba","takrorlash","mahorat"],x:"Malaka — ishni o‘zlashtirish orqali orttirilgan tajriba; ko‘nikma amallarni takrorlab yaxshiroq bajarishdan paydo bo‘ladi."},
  {t:"Xatodan o‘rganish",e:"🥛",k:["to‘kilgan sut","sabrli ona","tajriba"],x:"Ona o‘g‘lini urishmadi; bo‘lajak olim xatolar yangi bilim olish imkoniyati ekanini tushundi."},
  {t:"Kasblar olami",e:"👷",k:["40 mingdan ortiq","5 yo‘nalish","to‘g‘ri tanlov"],x:"Yo‘nalishlar: inson–inson, inson–tabiat, inson–belgi, inson–badiiy obraz, inson–texnika."},
  {t:"Qahramon zamondoshlar",e:"🚒",k:["Hayitmatov","Tobias","fidoyilik"],x:"O‘t o‘chiruvchi J. Hayitmatov va shifokor S. Tobias bolalar hayotini saqlab qolishgan."}]},
 q:[
 {t:"m",q:"Gyote fikricha, bilimning o‘zi yetarli emas, yana nima kerak?",a:["Uni amalda qo‘llay bilish","Uni yoddan aytib berish","Uni boshqalardan sir tutish","Uni daftarga ko‘chirib qo‘yish"],e:"«Istakning o‘zi yetarli emas, harakatlanish kerak»."},
 {t:"m",q:"Kasb-hunar va ishni o‘zlashtirish orqali orttirilgan tajriba nima deyiladi?",a:["Malaka","Iste’dod","Qadriyat","Qiziqish"],e:"Darslik ta’rifi: bu — malaka."},
 {t:"m",q:"Sut to‘kib yuborgan bolaga onasi qanday munosabatda bo‘ldi?",a:["Birga tozalab, boshqa usulni sinab ko‘rdi","Qattiq tanbeh berib, jazoladi","Oshxonaga kirishni taqiqlab qo‘ydi","Indamay o‘zi tozalab chiqdi"],e:"Shu tariqa bola idishni to‘g‘ri ushlashni o‘rgandi."},
 {t:"m",q:"Olimning xulosasiga ko‘ra, xatolar nima?",a:["Yangi bilim olish imkoniyati","Qo‘rqish uchun jiddiy sabab","Qobiliyatsizlikning belgisi","Ishni tashlash uchun asos"],e:"Xato qilishdan qo‘rqmaslik kerak."},
 {t:"m",q:"Darslikda keltirilishicha, dunyoda qancha kasb bor?",a:["40 mingdan ortiq","4 mingga yaqin","400 ga yaqin","4 milliondan ortiq"],e:"Olimlar 40 mingdan ortiq kasb borligini ta’kidlaydi."},
 {t:"m",q:"Mashina va mexanizmlar bilan ishlaydigan kasblar qaysi yo‘nalishga kiradi?",a:["Inson – texnika","Inson – tabiat","Inson – inson","Inson – badiiy obraz"],e:"Texnik obyektlar bilan o‘zaro bog‘liq."},
 {t:"m",q:"Jamoliddin Hayitmatov «Jasorat» medaliga nima uchun sazovor bo‘ldi?",a:["Yong‘indan olti o‘quvchini qutqargani uchun","Sport musobaqasida g‘olib bo‘lgani uchun","Behush bolalarni davolagani uchun","Yangi texnika ixtiro qilgani uchun"],e:"U yigirma yillik tajribali o‘t o‘chiruvchi."},
 {t:"m",q:"Sergey Tobias qaysi soha mutaxassisi?",a:["Otolaringolog shifokor","O‘t o‘chiruvchi","Veterinar","Muhandis"],e:"Quloq, tomoq, burun kasalliklarini davolaydi."},
 {t:"tf",q:"Ona tilini o‘rganish fikr va mulohazalarni bayon etishga o‘rgatadi.",a:true,e:"Xorijiy tillar esa dunyo xalqlari bilan hamkorlikda asqatadi."},
 {t:"tf",q:"Mutaxassislikni egallash uchun kasbga qiziqishning ahamiyati yo‘q.",a:false,e:"Yaxshi o‘qish va kasbga ko‘proq qiziqish kerak."},
 {t:"tf",q:"Ba’zi kasblar uchun aniqlik va yuqori intizom talab etiladi.",a:true,e:"Har bir kasbga oid muayyan xislatlar zarur."},
 {t:"f",q:"Qaysi kasbni tanlamoqchisiz? Unga qanday bilim va xislatlar kerak?",e:"Javobda kasb, o‘rganiladigan fanlar va zarur xislatlar (sabr, aniqlik, mas’uliyat va h.k.) ko‘rsatiladi."}]},

{id:"m11",n:"17–18-mavzu",t:"Zamonaviy texnologiyalar ezgulik xizmatida",b:3,
 map:{c:"Zamonaviy texnologiyalar",br:[
  {t:"Hayotdagi o‘rni",e:"📱",k:["mobil aloqa","internet","maishiy texnika"],x:"Texnologiyalar aloqa, xarid, o‘qish va uy ishlarini yengillashtiradi."},
  {t:"Atamalar",e:"💻",k:["raqamli olam","media","raqamli media"],x:"Media — axborotni saqlash, qayta ishlash va uzatish vositalari; raqamli media — elektron axborot va aloqa vositalari."},
  {t:"Afzallik va zarar",e:"⚖️",k:["bilim olish","qaramlik","sog‘liq"],x:"Smartfon bilim va til o‘rganishga yordam beradi, lekin sog‘liqqa zarar va qaramlik keltirishi mumkin."},
  {t:"Me’yor",e:"⏱️",k:["2–3 soat","reja","to‘xtatish"],x:"Qurilmadan kuniga 2–3 soatdan oshiq foydalanmaslik, noxushlik sezilsa darhol to‘xtatish kerak."},
  {t:"Anvar hikoyasi",e:"👨‍👧‍👦",k:["dadaning so‘zi","kitob","Oysha bilan o‘yin"],x:"Anvar telefonni qo‘yib, xonasini tartibga soldi, kitob o‘qidi va singlisi bilan o‘ynab, zavq oldi."}]},
 q:[
 {t:"m",q:"Axborotni saqlash, qayta ishlash va uzatishga xizmat qiluvchi vositalar nima deyiladi?",a:["Media","Ekslibris","Stress","Malaka"],e:"Darslikdagi media ta’rifi."},
 {t:"m",q:"Qaysi biri raqamli mediaga misol?",a:["Veb-sayt va elektron kitob","Qo‘lda yozilgan xat","Devorga osilgan qog‘oz xarita","Maktab doskasidagi bo‘r"],e:"Kompyuter dasturlari, raqamli video va audio, veb-saytlar, elektron nashrlar."},
 {t:"m",q:"Darslik qurilmalardan bir kunda qancha vaqtdan oshiq foydalanmaslikni maslahat beradi?",a:["2–3 soatdan","6–7 soatdan","10–12 soatdan","24 soatdan"],e:"Maslahat: bir kunda 2–3 soatdan oshirmang."},
 {t:"m",q:"Texnologiyadan foydalanganda o‘zingizni noxush his qilsangiz, nima qilish kerak?",a:["Foydalanishni darhol to‘xtatish","Ekran yorug‘ligini oshirish","Boshqa o‘yinga o‘tib olish","Ishni oxirigacha davom ettirish"],e:"Qurilma va internetdan foydalanish darhol to‘xtatiladi."},
 {t:"m",q:"Qaysi biri smartfonning kamchiligi sifatida ko‘rsatilgan?",a:["Unga bog‘lanib qolish","Matn yuborish imkoni","Til o‘rganishga yordam","So‘zlashish imkoni"],e:"Kamchiliklar: qimmatlik, to‘lovlar, sog‘liqqa zarar, qaramlik."},
 {t:"m",q:"Dadasining so‘zidan keyin Anvar nima qildi?",a:["Xonasini tartiblab, kitob o‘qidi","Yangi o‘yin yuklab oldi","Televizor oldiga o‘tirdi","Uxlashga yotib qoldi"],e:"So‘ng singlisi Oysha bilan hovlida o‘ynadi."},
 {t:"m",q:"Anvar qaysi qarorga keldi?",a:["Bo‘sh vaqtni oilaga ko‘proq bag‘ishlash","Telefonni tunda ishlatishga o‘tish","Faqat yolg‘iz o‘ynashni davom ettirish","Kitob o‘qishni keyinga qoldirish"],e:"U oila bilan vaqt o‘tkazish zavqini angladi."},
 {t:"m",q:"Bo‘sh vaqtda darslik nimani tavsiya qiladi?",a:["Oila davrasida suhbat, sayr va sport","Tungi vaqtda film tomosha qilish","Bir nechta qurilmani birga ishlatish","Xonada yolg‘iz o‘yin o‘ynash"],e:"Ochiq havoda sayr va sport foydali."},
 {t:"tf",q:"Texnologiyalar yordamida chet tillarni mustaqil o‘rganish mumkin.",a:true,e:"Audio, video va matnlar orqali."},
 {t:"tf",q:"Texnologiyalardan me’yorsiz foydalanish oiladagi munosabatlarga ta’sir qilmaydi.",a:false,e:"Sog‘liqqa ham, yaqinlar o‘rtasidagi munosabatlarga ham salbiy ta’sir qiladi."},
 {t:"tf",q:"Ayrim ishlarni texnologiyalarsiz bajarishning ham o‘z afzalliklari bor.",a:true,e:"Masalan, yuzma-yuz suhbat."},
 {t:"f",q:"Texnologiyali va texnologiyasiz mashg‘ulotlar o‘rtasida me’yorni qanday o‘rnatasiz?",e:"Kun rejasini tuzish, ekran vaqtini cheklash, sayr, sport va oila davrasiga vaqt ajratish."}]},

{id:"m12",n:"19–20-mavzu",t:"Salomatlik – ulkan boylik",b:3,
 map:{c:"Salomatlik",br:[
  {t:"Ibn Sinoning 5 tabibi",e:"🩺",k:["ozodalik","badantarbiya","parhez, mizoj, kayfiyat"],x:"Besh tabib: ozodalik, badantarbiya, parhez, mizoj, kayfiyat."},
  {t:"Chiniqish",e:"🏃",k:["sport","ochiq havo","kun tartibi"],x:"Badanni chiniqtirishning uch vositasi: badantarbiya, sport, ochiq havodagi mashg‘ulot."},
  {t:"Zararli odatlar",e:"🚭",k:["chekish","nikotin","shirinlik"],x:"Tamakidagi nikotin organizmga zarar va qaramlik keltiradi. Zararli odatdan qutulish insonning o‘z qo‘lida."},
  {t:"Stress",e:"🌀",k:["toliqish","musiqa","ulashish"],x:"Stress — tashqi ta’sirlardan jismoniy yoki ruhiy toliqish. Yaqinlar bilan bo‘lishish, musiqa, mashq, dam olish yordam beradi."},
  {t:"Vitaminlar",e:"🥕",k:["A — ko‘z","C — himoya","D — tish"],x:"A vitamini ko‘z va o‘sishga, C kasallikka qarshi kurashga, D tishlarga foydali."}]},
 q:[
 {t:"m",q:"Ibn Sino aytgan besh tabib qatoriga qaysi biri kiradi?",a:["Badantarbiya","Dorixona","Boylik","Uyqusizlik"],e:"Ozodalik, badantarbiya, parhez, mizoj, kayfiyat."},
 {t:"m",q:"«Badanning salomat va quvvatli bo‘lmog‘i insonga eng kerakli narsadur» fikri kimniki?",a:["Abdulla Avloniy","Alisher Navoiy","Ibn Arabshoh","Luqmoni hakim"],e:"O‘qish va o‘rganish uchun kuchli tana lozim."},
 {t:"m",q:"Amir Temurning tashqi qiyofasini so‘z bilan tasvirlagan tarixchi kim?",a:["Ibn Arabshoh","Ibn Sino","Beruniy","Avloniy"],e:"U Temurni qad-qomati kelishgan, kuchli deb ta’riflagan."},
 {t:"m",q:"Tamaki tarkibidagi qaysi modda odamni o‘ziga tobe qiladi?",a:["Nikotin","Vitamin","Glyukoza","Kalsiy"],e:"Nikotin organizm uchun zararli."},
 {t:"m",q:"Luqmoni hakim eng shirin lazzatni nimada deb bilgan?",a:["Sog‘-salomatlikda","Mol-dunyoda","Shirin taomda","Uzoq uyquda"],e:"«Eng shirin lazzat sog‘-salomatlikda ekanini angladim»."},
 {t:"m",q:"Ko‘rish faoliyatini yaxshilaydigan, sabzida uchraydigan vitamin qaysi?",a:["A vitamini","B2 vitamini","C vitamini","D vitamini"],e:"A vitamini bo‘yni o‘stiradi, ko‘z faoliyatini yaxshilaydi."},
 {t:"m",q:"C vitamini yetishmasa, nima kuzatiladi?",a:["Tez shamollash va kasallanish","Bo‘yning juda tez o‘sishi","Ko‘rishning keskin yaxshilanishi","Tishlarning mustahkamlanishi"],e:"Organizmning kurashuvchanlik qobiliyati susayadi."},
 {t:"m",q:"Stressdan chiqishga darslik qaysi usulni tavsiya etadi?",a:["Yoqtirgan musiqani tinglash","Uyqu vaqtini qisqartirish","Hislarni hammadan yashirish","Ovqatni o‘tkazib yuborish"],e:"Shuningdek, yaqinlar bilan o‘rtoqlashish, yengil mashq."},
 {t:"tf",q:"Mizoj va kayfiyat Ibn Sino aytgan tabiblar qatoriga kiradi.",a:true,e:"To‘rtinchisi — mizoj, beshinchisi — kayfiyat."},
 {t:"tf",q:"D vitamini kamayib ketsa, tishlar yanada mustahkam bo‘lib qoladi.",a:false,e:"Aksincha, tishlar tez sinuvchan bo‘ladi va yemiriladi."},
 {t:"tf",q:"Muhim musobaqa oldidan yengil jismoniy mashq asabni tinchlantiradi.",a:true,e:"U fikrni bir joyga jamlashga ham yordam beradi."},
 {t:"f",q:"Salomatligingizga foyda va zarar keltiradigan odatlarni sanab, bittasini qanday o‘zgartirishingizni yozing.",e:"Foyda: vaqtida ovqatlanish, harakat, ozodalik. Zarar: pala-partish ovqatlanish, dam olmaslik."}]},

{id:"m13",n:"21–22-mavzu",t:"Do‘stlik va mehr-oqibat",b:3,
 map:{c:"Do‘stlik",br:[
  {t:"Chin do‘stlik",e:"🤗",k:["samimiyat","yordam","quvonch va tashvish"],x:"Nodira hamma bilan yaqin bo‘lish hali chin do‘stlik emasligini tushundi."},
  {t:"Oltin qoidalar",e:"🌟",k:["hurmat","tushunish","ishonchlilik"],x:"Chin do‘stlar hurmat qiladi, kayfiyatni tushunadi, qiyin damda yordam beradi, ozor bermay kamchilikni aytadi."},
  {t:"Munosabat o‘rnatish",e:"💬",k:["umumiy qiziqish","diqqat","bag‘rikenglik"],x:"Qiziqishi o‘xshash odam bilan suhbatlashing, telefonga chalg‘imang. Do‘st og‘ir kunda bilinadi."},
  {t:"Ishonch",e:"🔑",k:["sandiq","va’da","sir"],x:"Sandiqni ochgan do‘st va va’dasini buzgan tulki ishonchni yo‘qotdi."},
  {t:"Do‘stni xafa qilma",e:"🪞",k:["Ra’no","Munisa","o‘z kamchiligi"],x:"Boshqaning kamchiligini tanqid qilib, o‘zinikini sezmaslik do‘stlikka zarar yetkazadi."}]},
 q:[
 {t:"m",q:"«Mening do‘stim» mashqida Nodira bilan nima bo‘ldi?",a:["Unga hech kim tilak bermadi","U eng ko‘p tilak oldi","U mashqqa qatnashmadi","U tilaklarni yo‘qotib qo‘ydi"],e:"U sinfda tilak olmagan yagona o‘quvchi bo‘ldi."},
 {t:"m",q:"Onasi Nodiraga do‘stlikni nima bilangina qozonib bo‘lmasligini aytdi?",a:["Shirin so‘z va tabassum bilan","Samimiy g‘amxo‘rlik bilan","Qiyin kundagi yordam bilan","Doimiy sadoqat bilan"],e:"Do‘stning yonida quvonch va tashvishda turish kerak."},
 {t:"m",q:"Chin do‘stlikning «oltin qoidalari»ga qaysi biri mos?",a:["Ozor bermay kamchilikni aytish","Do‘stni kamsitib to‘g‘rilash","Faqat foydali paytda yonida bo‘lish","Sirini boshqalarga yetkazish"],e:"Do‘stlar ko‘ngilga ozor yetkazmay kamchilikni aytadi."},
 {t:"m",q:"Darslikda keltirilgan xalq maqoli qaysi?",a:["Do‘st og‘ir kunda bilinadi","Yolg‘onning umri qisqa","Sabr — yutuq kaliti","Salomga yarasha alik"],e:"Haqiqiy do‘stlar doim yordamga shay."},
 {t:"m",q:"Badavlat kishi sandiqqa aslida nima solgan edi?",a:["Toshlar","Tillalar","Kitoblar","Matolar"],e:"U do‘stini sinash uchun tosh solgan."},
 {t:"m",q:"Do‘stining sandiqni ochgani qanday ma’lum bo‘ldi?",a:["Ichida tosh borligini aytib qo‘ydi","Qo‘shnilar buni ko‘rib aytishdi","Kalit sinib qolgan edi","Sandiq boshqa joyda topildi"],e:"«Boylik toshlar ekanligini qanday bilding?»"},
 {t:"m",q:"Ayiq va bug‘u nega tulkidan ranjidi?",a:["U va’dasini buzib, sirni yoydi","U mevalarni yolg‘iz yeb qo‘ydi","U ularni o‘yinga qo‘shmadi","U ko‘ldagi baliqlarni tutib oldi"],e:"Tulki topilgan mevalar sirini barcha hayvonlarga aytdi."},
 {t:"m",q:"Ra’no va Munisa suhbatida Munisaning kamchiligi nima edi?",a:["O‘z kamchiligini ko‘rmaslikka urinishi","Hech qachon fikr bildirmasligi","Doim boshqalarni maqtab yurishi","Xatosi uchun tez kechirim so‘rashi"],e:"U boshqalarni tanqid qilib, o‘zinikini sezmaslikni afzal ko‘rdi."},
 {t:"tf",q:"Do‘stlikda do‘stlarning soni eng muhim narsa hisoblanadi.",a:false,e:"Muhimi — kimlar samimiy bo‘lishi va qo‘llab-quvvatlashi."},
 {t:"tf",q:"Shartlarga asoslangan o‘zaro hamkorlikning o‘zi hali do‘stlik emas.",a:true,e:"Unda do‘stlik rishtalari bo‘lmaydi."},
 {t:"tf",q:"Do‘st bilan suhbatda telefonga chalg‘imaslik tavsiya etiladi.",a:true,e:"Suhbatdoshga e’tibor berish kerak."},
 {t:"f",q:"Sadoqatli do‘stning uchta belgisini yozing va misol keltiring.",e:"Masalan: sirni saqlaydi, qiyin damda yonda bo‘ladi, kamchilikni kechiradi va yordam beradi."}]},

{id:"m14",n:"23–24-mavzu",t:"Rostgo‘ylik va halollik",b:3,
 map:{c:"Rostgo‘ylik va halollik",br:[
  {t:"Yolg‘on oqibati",e:"🐺",k:["cho‘pon bola","aldov","ishonch yo‘qolishi"],x:"Bo‘ri haqida yolg‘on baqirgan cho‘ponga haqiqiy xavfda hech kim yordamga kelmadi."},
  {t:"Halollik",e:"💎",k:["to‘g‘riso‘zlik","so‘z va ish birligi","go‘zal fazilat"],x:"Halol odam rost so‘zlaydi, aytgan gapi bilan qilgan ishi bir xil bo‘ladi."},
  {t:"Halol bola",e:"🪓",k:["temir bolta","oltin","kumush"],x:"Bola o‘ziniki bo‘lmagan oltin va kumush boltani olmadi, mukofotiga ikkalasini oldi."},
  {t:"Hayotiy tanlov",e:"📱",k:["telefon","qaytim","javoblar"],x:"Topilgan telefon egasini izlash, topilgan javoblarni o‘qituvchiga qaytarish — halol yo‘l."},
  {t:"Hikmatlar",e:"📜",k:["yolg‘onning umri","Shekspir","tinch ko‘ngil"],x:"«Yolg‘onning umri qisqa». Rostgo‘y va haqiqatparvarning ko‘ngli tinch bo‘ladi."}]},
 q:[
 {t:"m",q:"Cho‘pon bola nima uchun «Bo‘ri!» deb yolg‘on gapirdi?",a:["Zerikib, nayrang qilmoqchi bo‘lgani uchun","Qo‘ylarini sotmoqchi bo‘lgani uchun","Odamlarni to‘yga chaqirish uchun","Bo‘ri sharpasini ko‘rgandek bo‘lgani uchun"],e:"U juda zerikib ketgan edi."},
 {t:"m",q:"Bo‘rilar chindan hujum qilganda nima bo‘ldi?",a:["Yordamga hech kim kelmadi","Hamma tezda yetib keldi","Bola bo‘rilarni quvib soldi","Itlar qo‘ylarni qutqardi"],e:"Aldangan odamlar endi ishonmadi."},
 {t:"m",q:"«Halol odamga yetkazish mumkin bo‘lgan eng katta zarar — uni halolsizlikda ayblash» fikri kimniki?",a:["Uilyam Shekspir","Gyote","Demokrit","Mahatma Gandi"],e:"Ingliz yozuvchisi U. Shekspir."},
 {t:"m",q:"Halol bola ko‘ldan chiqqan cholga qaysi bolta o‘ziniki ekanini aytdi?",a:["Temir bolta","Oltin bolta","Kumush bolta","Mis bolta"],e:"U faqat o‘ziga tegishlisini oldi."},
 {t:"m",q:"Chol halolligi uchun bolaga nima sovg‘a qildi?",a:["Oltin va kumush boltalarni","Bir qop o‘tin va non","Yangi kiyim va poyabzal","Ko‘ldan tutilgan baliqni"],e:"«Halolliging uchun» ikkala boltani berdi."},
 {t:"m",q:"Avtobusda birovning telefonini topsangiz, halol yo‘l qaysi?",a:["Egasini topishga harakat qilish","Topilmadi deb o‘zida saqlash","Tezda sotib, pulini ishlatish","Do‘stga sovg‘a qilib berish"],e:"Birovning narsasi egasiga qaytarilishi kerak."},
 {t:"m",q:"Nazorat ishi javoblarini topib olgan halol o‘quvchi nima qiladi?",a:["Qaramay o‘qituvchiga qaytaradi","Nazoratda ulardan foydalanadi","Do‘stlariga tarqatib chiqadi","Yodlab, joyiga qo‘yib qo‘yadi"],e:"Bu — halollikka mos tanlov."},
 {t:"m",q:"Yo‘lakdan 50 ming so‘m topgan Omon to‘g‘ri yo‘l tutishi uchun nima qilishi kerak edi?",a:["Maktab ma’muriyatiga topshirishi","Cho‘ntagida saqlab qo‘yishi","Do‘stlari bilan bo‘lib olishi","Yana yo‘lakka tashlab ketishi"],e:"Pul birovniki: uni topshirish lozim."},
 {t:"tf",q:"Hech kim ko‘rmagan bo‘lsa, topib olingan pulni o‘zida qoldirish halollikdir.",a:false,e:"Halollik kuzatuvchi bor-yo‘qligiga bog‘liq emas."},
 {t:"tf",q:"Halol odamning aytgan gapi bilan qilgan ishi bir xil bo‘ladi.",a:true,e:"Rostgo‘ylik — halollik belgisi."},
 {t:"tf",q:"«Yolg‘onning umri qisqa» — xalq maqoli.",a:true,e:"Cho‘pon hikoyasi oldidan shu maqol berilgan."},
 {t:"f",q:"Sotuvchi sizga adashib ortiqcha qaytim bersa, nima qilasiz? Nega?",e:"Qaytarib beraman: pul meniki emas, sotuvchi kamomad uchun javob berishi mumkin; bu halollik."}]},

{id:"m15",n:"25-mavzu",t:"Ishonchli va ishonchsiz axborotlar",b:3,
 map:{c:"Axborotni tekshirish",br:[
  {t:"Soxta axborot",e:"❌",k:["uydirma","mish-mish","afsona"],x:"Soxta va yolg‘on axborot — voqea yoki inson haqida haqiqatdan yiroq mish-mish va asossiz ma’lumotlar."},
  {t:"Tarix",e:"📰",k:["1835-yil","«New York Sun»","Oy haqida"],x:"Bosma nashrlardagi birinchi yolg‘on axborot — 1835-yilda Oy va undagi jonzotlar haqidagi uydirma maqolalar."},
  {t:"Maqsad",e:"💰",k:["o‘quvchi soni","daromad","tarqatuvchi"],x:"Uydirmalar ko‘proq o‘quvchi yig‘ish va daromad olishga xizmat qiladi."},
  {t:"Baholash",e:"🔍",k:["diqqat bilan o‘qish","manba","taqqoslash"],x:"Diqqat bilan o‘qing, manbani aniqlang, rostligini boshqa manbalardan tekshiring."},
  {t:"Mediasavodxonlik",e:"🧠",k:["tahlil","baholash","media yaratish"],x:"Mediasavodxonlik — axborotni tahlil qilish, baholash va media mahsulot yarata olish qobiliyati."}]},
 q:[
 {t:"m",q:"Bosma nashrlardagi eng birinchi yolg‘on axborot deb qaysi uydirma ko‘rsatilgan?",a:["Oy va undagi jonzotlar haqidagi maqolalar","Okeandagi akula haqidagi videotasvir","Tog‘ chang‘ichisiga oid videotasvir","Mars sayyorasiga uchish haqidagi xabar"],e:"1835-yilda «New York Sun» nashrida e’lon qilingan."},
 {t:"m",q:"Bu uydirma maqolalar qaysi nashrda chiqqan?",a:["«New York Sun»","«London Times»","«Paris Match»","«Daily Moon»"],e:"Darslik «New York Sun» nashrini ko‘rsatadi."},
 {t:"m",q:"Internetda uydirma axborot tarqatish nimaga yordam beradi, deb aytilgan?",a:["O‘quvchi sonini va daromadni oshirishga","Ilmiy kashfiyotlarni tez tasdiqlashga","Odamlarning xotirasini kuchaytirishga","Xalqlar o‘rtasida ishonch o‘rnatishga"],e:"Ko‘proq o‘quvchi — ko‘proq daromad."},
 {t:"m",q:"Axborotni baholashda manbani aniqlash uchun nima qilinadi?",a:["Sayt egalari va muallif haqida ma’lumot to‘planadi","Sarlavhaning uzunligi va rangi o‘lchab ko‘riladi","Xabar darhol barcha tanishlarga yuboriladi","Faqat rasmlarning chiroyliligiga qaraladi"],e:"Manbani aniqlash — muhim bosqich."},
 {t:"m",q:"Axborot rostligini tasdiqlash uchun qaysi savol muhim?",a:["Boshqa manbalar qanday ma’lumot beryapti?","Bu xabarni nechta odam yoqtirib qo‘ydi?","Xabar qaysi rangli harflarda yozilgan?","Video necha daqiqa davom etadi?"],e:"Boshqa manbalar bilan taqqoslash kerak."},
 {t:"m",q:"Avstraliyalik telekompaniya joylagan mashhur videoda kim aks etgan?",a:["Tog‘ chang‘ichisi","Sohildagi baliqchi","Chuqurdagi g‘avvos","Uchuvchi sayyoh"],e:"Chang‘ichi ortidan quvayotgan ayiq videosi soxta misol sifatida o‘rganiladi."},
 {t:"m",q:"Mediasavodxonlik nima?",a:["Media axborotini tahlil qilish va baholay olish","Qurilmani tez ishlatib, tez yozish mahorati","Har bir xabarga darhol ishonish odati","Faqat gazeta o‘qish bilan cheklanish"],e:"U media mahsulot yarata olishni ham o‘z ichiga oladi."},
 {t:"m",q:"Darslikda yolg‘on axborotga misol qilingan ikkinchi videoda nima tasvirlangan?",a:["Akula va odamning «kurashi»","Kitning kemani yutishi","Delfinning bola bilan o‘yini","Ayiqning daraxtga chiqishi"],e:"Avstraliya sohillarida olingan deb tarqatilgan video."},
 {t:"tf",q:"Internetdagi har qanday xabar va ma’lumot doim haqiqat bo‘ladi.",a:false,e:"Ba’zilarida yolg‘on va isbotlanmagan ma’lumotlar bor."},
 {t:"tf",q:"Videotasvir orqali uzatilgan voqeaga ham tekshirmay ishonib bo‘lmaydi.",a:true,e:"Internetda soxta videolar ko‘p."},
 {t:"tf",q:"Soxta axborot tarqatuvchilarning maqsadlarini bilish foydali.",a:true,e:"Bu aldanib qolmaslikka yordam beradi."},
 {t:"f",q:"Muhim yangilik haqida soxta video tarqalsa, qanday oqibat bo‘lishi mumkin? Uni qanday tekshirasiz?",e:"Vahima va noto‘g‘ri qarorlar. Manba va muallifni aniqlash, ishonchli manbalar bilan solishtirish, tekshirmay tarqatmaslik."}]},

{id:"m16",n:"26–27-mavzu",t:"Oila – qadriyatlar beshigi",b:4,
 map:{c:"Oila va qadriyatlar",br:[
  {t:"Oila nima",e:"🏠",k:["jamiyat qismi","umumiy maqsad","immunitet"],x:"Oila — qarindoshlargina emas, qiziqish, his-tuyg‘u va maqsadlari yaqin odamlar; unda qiyinchilikni yengadigan «immunitet» hosil bo‘ladi."},
  {t:"Qadriyatlar",e:"💎",k:["an’ana","urf-odat","hurmat"],x:"Oilaviy qadriyatlar — barcha a’zolar qadrlaydigan, hurmat qilinadigan an’ana va urf-odatlar."},
  {t:"Konstitutsiya",e:"📘",k:["asosiy bo‘g‘in","muhofaza","63-modda"],x:"Oila jamiyatning asosiy bo‘g‘ini bo‘lib, jamiyat va davlat muhofazasida bo‘lish huquqiga ega."},
  {t:"Ahillik",e:"🤝",k:["donishmand","o‘zi xohlash","samimiyat"],x:"Yuz kishilik oila ahillik uchun avvalo o‘zlari xohlashi kerakligini angladi."},
  {t:"Oila a’zolari",e:"👨‍👩‍👧‍👦",k:["ota-ona ibrati","opa-singil","aka-uka"],x:"Ota-ona — ibrat va himoya; opa-singil, aka-uka bir-birining sirdoshi va suyanchig‘i."}]},
 q:[
 {t:"m",q:"Oilaviy qadriyatlar nima?",a:["Barcha a’zolar qadrlaydigan an’ana va urf-odatlar","Uydagi qimmatbaho buyum va jihozlar to‘plami","Faqat bayramda beriladigan sovg‘alar ro‘yxati","Oilaning oylik daromadi va xarajat rejasi"],e:"Ular oila uchun muhim va hurmat qilinadi."},
 {t:"m",q:"Darslikka ko‘ra, oilada insonda nima hosil bo‘ladi?",a:["Qiyinchiliklarni yengadigan «immunitet»","Tayyor holdagi kasbiy malaka","Boshqalarga bo‘lgan befarqlik","Chet tillarni biladigan iste’dod"],e:"Bu «immunitet» hayot davomida yordam beradi."},
 {t:"m",q:"«Oila jamiyatning asosiy bo‘g‘inidir» degan norma qaysi hujjatdan olingan?",a:["O‘zbekiston Konstitutsiyasidan","Maktab ichki tartibidan","Yo‘l harakati qoidalaridan","Mahalla yig‘ilishi bayonidan"],e:"Konstitutsiyaning 63-moddasi."},
 {t:"m",q:"Donishmand yuz kishilik oilaga nima dedi?",a:["O‘zingiz xohlamaguncha hech kim o‘rgatolmaydi","Har biringiz alohida uyda yashashingiz kerak","Eng kattangizga so‘zsiz bo‘ysunsangiz bo‘ldi","Mol-mulkni teng bo‘lsangiz, ahil bo‘lasiz"],e:"Baxtli bo‘lish uchun nima kerakligini o‘zlari tushunishi lozim."},
 {t:"m",q:"«Hech bir xalq oilaviy munosabatlarsiz mavjud bo‘la olmaydi» fikri muallifi kim?",a:["Abu Rayhon Beruniy","Abu Ali ibn Sino","Alisher Navoiy","Abdurahmon Jomiy"],e:"Beruniy: oila yaratish barcha millatlar uchun tabiiy."},
 {t:"m",q:"Ota farzandiga bergan to‘rt nasihatga qaysi biri kiradi?",a:["Kitob mutolaasi va jismoniy tarbiya","Mol-dunyo to‘plashga shoshilish","Faqat yolg‘iz ishlashga odatlanish","Tengdoshlar bilan doim bellashish"],e:"Yana: ta’lim-tarbiya olish, chin do‘st topish, to‘g‘riso‘z va kamtar bo‘lish."},
 {t:"m",q:"Matnda mehr va sadoqat, iffat va hayo namunasi deb kim ta’riflanadi?",a:["Opa","Uka","Aka","Amaki"],e:"Opa — singil va uka uchun namuna."},
 {t:"m",q:"Milliy qadriyatlarimizning o‘zagiga nima kiradi?",a:["Kattalar va ustozlarga hurmat ko‘rsatish","Har bir modani birinchi bo‘lib qabul qilish","Faqat o‘z manfaatini himoya qilish","Qarindoshlardan uzoqroq yurish"],e:"Hurmat va oila, el-yurtga sadoqat."},
 {t:"tf",q:"Har bir oilaning yozilmagan o‘z qonunlari bor.",a:true,e:"Ularga amal qilish qadriyatlar shakllanishiga sabab bo‘ladi."},
 {t:"tf",q:"Insonning shaxs sifatida shakllanishi faqat voyaga yetgach, oiladan tashqarida boshlanadi.",a:false,e:"Shaxs sifatida shakllanish aynan oiladan boshlanadi."},
 {t:"tf",q:"«Oila tinch — yurt tinch» maqoli darslikda keltirilgan.",a:true,e:"Yana: «Oila — qo‘sh ustunli ayvon»."},
 {t:"f",q:"Oilangizdagi qaysi qadriyatni eng muhim deb bilasiz? Nima uchun?",e:"Masalan: hurmat, mehr, o‘zaro yordam, ishonch — misol bilan asoslanadi."}]},

{id:"m17",n:"28–29-mavzu",t:"Oilaviy kitobxonlik",b:4,
 map:{c:"Oilaviy kitobxonlik",br:[
  {t:"Kitob foydasi",e:"📚",k:["dunyoqarash","nutq","xotira"],x:"Kitob dunyoqarashni boyitadi, nutqni o‘stiradi, xotirani mustahkamlaydi — sadoqatli hamroh."},
  {t:"Sharq an’anasi",e:"🕯️",k:["oila davrasi","ma’naviy aloqa","ishonch"],x:"Oilada birga kitob o‘qish shaxsni shakllantiradi va ishonchli munosabat o‘rnatadi."},
  {t:"O‘qish malakasi",e:"🔖",k:["tanlay olish","esda saqlash","qayta o‘qish"],x:"Barchaga qiziqarli kitob tanlash, muhimini eslab qolish, yetkazish, qayta o‘qish."},
  {t:"Artobolevskiy",e:"🏅",k:["ovoz chiqarib","bobo kutubxonasi","oltin medal"],x:"Bolaligida kitob tinglagan olim keyin o‘zi o‘qib, katta muvaffaqiyatga erishdi."},
  {t:"Ekslibris",e:"🏷️",k:["egalik belgisi","muhr","shaxsiy kutubxona"],x:"Ekslibris — kitob muayyan odamga tegishli ekanini tasdiqlovchi belgi."}]},
 q:[
 {t:"m",q:"Kitob mutolaasi insonga qanday ta’sir qiladi?",a:["Nutqini o‘stirib, xotirasini mustahkamlaydi","Nutqini cheklab, xotirasini susaytiradi","Faqat jismoniy kuchini oshiradi","Faqat bo‘sh vaqtini band qiladi"],e:"Kitob insonni komillik sari yetaklaydi."},
 {t:"m",q:"«Agar yolg‘iz esang, hamdam kitobdur...» misralari kimniki?",a:["Abdurahmon Jomiy","Hamza Niyoziy","Alisher Navoiy","Rudakiy"],e:"Jomiy kitobni hamdam va nur deb ataydi."},
 {t:"m",q:"Oilaviy o‘qish uchun kitob qanday tanlanishi kerak?",a:["Barcha oila a’zolariga qiziqarli","Faqat eng qalin va qimmat","Faqat muqovasi chiroyli","Faqat bir kishiga yoqadigan"],e:"Kitob tanlay olish — muhim shart."},
 {t:"m",q:"I. I. Artobolevskiy bolaligida nimani yoqtirgan?",a:["Kitoblarni ovoz chiqarib o‘qib berishlarini","Kun bo‘yi hovlida to‘p o‘ynashni","Eski soatlarni buzib yig‘ishni","Rasm daftariga hayvon chizishni"],e:"Keyin bobosining kutubxonasidan foydalandi."},
 {t:"m",q:"Artobolevskiy qaysi nufuzli mukofot sovrindori?",a:["«Jeyms Uatt» oltin medali","«Jasorat» medali","«El-yurt hurmati» ordeni","Olimpiada oltin medali"],e:"Fizik-muhandislik sohasidagi xalqaro mukofot."},
 {t:"m",q:"Kitobning ma’lum odamga tegishli ekanini tasdiqlovchi belgi nima?",a:["Ekslibris","Mundarija","Annotatsiya","Sarvaraq"],e:"U muhr yoki imzo kabi egalikni bildiradi."},
 {t:"m",q:"Eng katta kitob haqidagi ma’lumotda uning og‘irligi qancha?",a:["1,5 tonna","150 kilogramm","15 tonna","15 kilogramm"],e:"Uni 30 olim va 300 ishchi to‘rt yilda yaratgan."},
 {t:"m",q:"Darslikka ko‘ra, dastlabki tarbiyani inson qayerda oladi?",a:["Oilada","Maktabda","Kutubxonada","Mahalla idorasida"],e:"Keyin maktabda jamoada tutishni o‘rganadi."},
 {t:"tf",q:"Sharq oilalarida davra qurib kitob o‘qish qadimiy an’ana hisoblanadi.",a:true,e:"U kattalar va bolalar o‘rtasidagi ma’naviy aloqa sharti."},
 {t:"tf",q:"Kitob o‘qiy olish uchun uni qayta o‘qishning foydasi yo‘q.",a:false,e:"Qayta o‘qish kitobxonlik ko‘nikmasini shakllantiradi."},
 {t:"tf",q:"Kitob insonni o‘qituvchi singari tarbiyalay oladi.",a:true,e:"Darslik kitobni muallim deb ataydi."},
 {t:"f",q:"Oilangizda mutolaani rivojlantirish uchun qanday taklif bergan bo‘lardingiz?",e:"Masalan: kechki o‘qish soati, birga kitob tanlash va muhokama, uy kutubxonasi."}]},

{id:"m18",n:"30-mavzu",t:"To‘g‘ri ovqatlanish qoidalari",b:4,
 map:{c:"To‘g‘ri ovqatlanish",br:[
  {t:"Ahamiyati",e:"💪",k:["salomatlik","mehnat qobiliyati","energiya"],x:"To‘g‘ri ovqatlanish salomatlik va mehnat qobiliyatini ta’minlovchi eng muhim omil."},
  {t:"Elementlar",e:"🧬",k:["makroelement","mikroelement","ichki a’zolar"],x:"Makro va mikroelementli mahsulotlar organizmga energiya ishlab chiqarish uchun zarur."},
  {t:"Maslahatlar",e:"🥗",k:["tabiiy mahsulot","meva-sabzavot","me’yorida tuz"],x:"Tabiiy mahsulot, har kuni meva-sabzavot, o‘simlik moylari, kun tartibi, uglevodni cheklash."},
  {t:"Kunlik tartib",e:"🍽️",k:["nonushta","tushlik","yengil kechki ovqat"],x:"Nonushta to‘yimli, tushlik suyuq va quyuq taomdan, kechki ovqat yengil bo‘lsin."},
  {t:"Qandli diabet",e:"🩸",k:["taomnoma","jismoniy mashq","nazorat"],x:"Bemor kasallikni taomnoma va yo‘riqnoma bilan nazorat qilishi, harakatli mashg‘ulot bilan shug‘ullanishi mumkin."}]},
 q:[
 {t:"m",q:"Darslikda shakar o‘rniga nimani iste’mol qilish ma’qul deyilgan?",a:["Asal","Konfet","Murabbo","Shokolad"],e:"Asal ichki a’zolarni sog‘aytiradi, immunitetni oshiradi."},
 {t:"m",q:"Qanday taomlardan saqlanish tavsiya etilgan?",a:["Qovurilgan taomlardan","Sabzavotli salatlardan","Yangi mevalardan","Sutli bo‘tqalardan"],e:"Ovqatni bir vaqtda yeb, qovurilganlardan saqlanish ma’qul."},
 {t:"m",q:"Organizmni maktabda kerak bo‘ladigan quvvat bilan ta’minlaydigan ovqatlanish bosqichi qaysi?",a:["Nonushta","Kechki ovqat","Tungi yegulik","Uyqu oldi choyi"],e:"Nonushta to‘yimli va foydali bo‘lishi kerak."},
 {t:"m",q:"Nonushtada nima yeyish tavsiya etilmaydi?",a:["Buterbrod","Bo‘tqa","Tvorog","Quymoq"],e:"Vitaminga boy bo‘tqa, quymoq, tvorog mumkin."},
 {t:"m",q:"Tushlik qanday bo‘lishi kerak?",a:["Suyuq va quyuq taomdan iborat","Faqat shirinlik va choydan","Faqat bitta buterbroddan","Faqat gazli ichimlik va nondan"],e:"Sabzavotli salatni ham unutmaslik kerak."},
 {t:"m",q:"Nega kechki ovqat yengil bo‘lishi lozim?",a:["To‘yimli ovqat hazmida a’zolar zo‘riqadi","Kechqurun ovqatning mazasi sezilmaydi","Kechqurun tanaga suv umuman kerakmas","Yengil taom bo‘yni darhol o‘stiradi"],e:"Zo‘riqish kasalliklar ehtimolini oshiradi."},
 {t:"m",q:"Sog‘lom turmush uchun ovqatlanish tartibi, sifati, miqdori va vaqtiga e’tibor berishni kim ta’kidlagan?",a:["Abu Ali ibn Sino","Abu Rayhon Beruniy","Abdulla Avloniy","Luqmoni hakim"],e:"Darslikdagi Ibn Sino hikmati."},
 {t:"m",q:"Qaysi maqol ovqatda me’yorni uqtiradi?",a:["Oz yemak — soz yemak","Oila tinch — yurt tinch","Sabr — yutuq kaliti","Xalqda bor — senda bor"],e:"«Oz demak — soz demak, oz yemak — soz yemak»."},
 {t:"tf",q:"Har kuni meva va sabzavot iste’mol qilish tavsiya etiladi.",a:true,e:"Bu darslikdagi maslahatlardan biri."},
 {t:"tf",q:"Tuzni qancha ko‘p ishlatsak, ovqatlanish shuncha to‘g‘ri bo‘ladi.",a:false,e:"Tuzdan me’yorida foydalanish kerak."},
 {t:"tf",q:"Velosiped minish va suzish profilaktik tadbirlar qatoriga kiradi.",a:true,e:"Qandli diabet haqidagi matnda aytilgan."},
 {t:"f",q:"O‘zingiz uchun bir kunlik foydali ovqatlanish tartibini tuzing.",e:"Masalan: nonushtaga bo‘tqa yoki tvorog; tushlikka suyuq va quyuq taom, salat; kechga yengil taom, meva."}]},

{id:"m19",n:"31–32-mavzu",t:"Ekologik xavflar",b:4,
 map:{c:"Ekologik xavflar",br:[
  {t:"Uch davr",e:"🕰️",k:["yig‘im-terim, ov","dehqonchilik","sanoat asri"],x:"Avval inson tabiatga bog‘liq edi, ~10 ming yil oldin dehqonchilik boshlandi, bugun sanoat va ilmiy kashfiyotlar asri."},
  {t:"Inson ta’siri",e:"🏭",k:["resurs qazish","chiqindi","zaharli gaz"],x:"Zavodlar, qurilish, kimyoviy va sanoat chiqindilari suv, tuproq va havoni ifloslaydi."},
  {t:"Tabiatning javobi",e:"🌡️",k:["global isish","ozon tuynugi","turlar yo‘qolishi"],x:"Ifloslanish, ozon tuynuklari, global isish, muzlik erishi, yangi kasalliklar."},
  {t:"Kataklizmlar",e:"🌊",k:["sunami","dovul","zilzila"],x:"Kataklizmlar soni so‘nggi asrda qariyb 20 baravar ko‘paydi."},
  {t:"Yechim",e:"🌳",k:["daraxt ekish","qayta ishlash","kislorod"],x:"Qog‘oz va plastik chiqindilarni yig‘ish, ko‘chat ekish. Bir katta daraxt yiliga taxminan 120 kg kislorod beradi."}]},
 q:[
 {t:"m",q:"Atrof-muhit va insoniyatning yo‘q bo‘lishiga olib keladigan muammo nima deyiladi?",a:["Ekologik muammo","Iqtisodiy muammo","Oilaviy muammo","Texnik nosozlik"],e:"Darslikdagi ta’rif."},
 {t:"m",q:"Jamiyat va tabiat munosabatining birinchi bosqichida odamlar nima bilan shug‘ullangan?",a:["Yig‘im-terim va ov bilan","Sanoat va zavod qurish bilan","Kosmosni o‘zlashtirish bilan","Neft va gaz qazish bilan"],e:"Hayot tabiiy sharoitga to‘liq bog‘liq edi."},
 {t:"m",q:"Insoniyat dehqonchilik va chorvachilikni taxminan qachon o‘rgandi?",a:["10 ming yil oldin","100 yil oldin","500 yil oldin","1 million yil oldin"],e:"Shundan keyin tabiatga ta’sir sezilarli oshdi."},
 {t:"m",q:"So‘nggi asrda kataklizmlar soni necha baravar ko‘paygan?",a:["Qariyb 20 baravar","Qariyb 2 baravar","Qariyb 100 baravar","Qariyb 5 baravar"],e:"Bugun yiliga ikki yuzdan ortiq hodisa ro‘y beradi."},
 {t:"m",q:"Qaysi biri inson tomonidan atmosferaga chiqariladigan zararli modda?",a:["Uglerod oksidi","Toza kislorod","Yomg‘ir suvi","Gul changi"],e:"Shuningdek, oltingugurt va azot oksidlari, freon."},
 {t:"m",q:"Tabiatning insonga «javobi» qatoriga qaysi biri kiradi?",a:["Global isish va muzliklar erishi","Foydali qazilmalarning ko‘payishi","Havo va suvning tozalanib borishi","Hayvon turlarining ko‘payishi"],e:"Shuningdek, ozon tuynuklari va ekotizimlar nobud bo‘lishi."},
 {t:"m",q:"Bitta katta daraxt yiliga taxminan qancha kislorod ishlab chiqaradi?",a:["120 kilogramm","12 kilogramm","1200 kilogramm","2 kilogramm"],e:"Bu uch kishilik oilaning bir yillik nafasiga yetarli."},
 {t:"m",q:"«Bizning birinchi ekobog‘» loyihasining maqsadi nima?",a:["Chiqindini qayta ishlash va ko‘kalamzorlashtirish","Maktab yonida yangi do‘kon va bozor ochish","O‘rmondan o‘tin tayyorlab, sotishni yo‘lga qo‘yish","Hayvonot bog‘iga noyob qushlar olib kelish"],e:"Qog‘oz va plastik yig‘ilib, tushgan mablag‘ga ko‘chat olinadi."},
 {t:"tf",q:"Hozirgi davrda tabiat inson yo‘q qilgan narsalarni tiklashga bemalol ulgurmoqda.",a:false,e:"Tabiat qayta tiklashga ulgurmayapti."},
 {t:"tf",q:"Aholi ko‘payishi bilan uning ehtiyojlari ham o‘smoqda.",a:true,e:"Natijada tabiatdan ko‘proq resurs olinmoqda."},
 {t:"tf",q:"Iqlim o‘zgarishi va atrof-muhit yomonlashuvi odamlar sog‘lig‘iga ham ta’sir qiladi.",a:true,e:"Yangi kasalliklar va epidemiyalar paydo bo‘lishi mumkin."},
 {t:"f",q:"Ekologik muammolarni hal qilishga hozirdan qanday yordam bera olasiz?",e:"Masalan: chiqindini saralash, suvni tejash, ko‘chat ekish, yaqinlarga tushuntirish."}]}
);
